-- Coleta de preços todo dia às 7h (Brasília) disparada pelo banco: o agendamento do GitHub deixou de rodar em alguns dias.
select cron.schedule('disparar-concorrencia', '0 10 * * *', $c$select net.http_post(url := 'https://api.github.com/repos/leandromarquescoelho-stack/nova/actions/workflows/concorrencia.yml/dispatches', body := '{"ref":"main"}'::jsonb, headers := jsonb_build_object('Authorization','Bearer '||(select decrypted_secret from vault.decrypted_secrets where name='github_token_carga'), 'Accept','application/vnd.github+json','X-GitHub-Api-Version','2022-11-28','User-Agent','nova-bi-carga'))$c$);
